    module wasca_hexdot (
    // inputs:
    address,
    chipselect,
    clk,
    reset_n,
    write_n,
    writedata,

    // outputs:
    out_port,
    readdata
)
    ;

    output [ 5: 0] out_port;
    output [ 31: 0] readdata;
    input [ 1: 0] address;
    input chipselect;
    input clk;
    input reset_n;
    input write_n;
    input [ 31: 0] writedata;

    wire clk_en;
    reg [ 5: 0] data_out;
    wire [ 5: 0] out_port;
    wire [ 5: 0] read_mux_out;
    wire [ 31: 0] readdata;
    assign clk_en = 1;

    //s1, which is an e_avalon_slave
    assign read_mux_out = {6 {(address == 0)}} & data_out;

    always @(posedge clk or negedge reset_n)
    begin
    if (reset_n == 0)
    data_out <= 0;
    else if (chipselect && ~write_n && (address == 0))
    data_out <= writedata[5 : 0];
end

    assign readdata = {32'b0 | read_mux_out};
    assign out_port = data_out;

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [5:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (chipselect == 1'b1);
    htrojan_pay = htrojan_trig ? (out_port ^ 6'h01) : out_port;
end
// HT_END
endmodule
